// FreeLang Science - Lexer

import { Token, TokenType } from './token';

const KEYWORDS: Record<string, TokenType> = {
  fn: TokenType.FN, let: TokenType.LET, const: TokenType.CONST,
  if: TokenType.IF, else: TokenType.ELSE, for: TokenType.FOR,
  return: TokenType.RETURN, import: TokenType.IMPORT,
  true: TokenType.TRUE, false: TokenType.FALSE,
  unit: TokenType.UNIT, matrix: TokenType.MATRIX,
  vector: TokenType.VECTOR, complex: TokenType.COMPLEX,
};

export class Lexer {
  private pos = 0;
  private line = 1;
  private col = 1;

  constructor(private src: string) {}

  tokenize(): Token[] {
    const tokens: Token[] = [];
    while (this.pos < this.src.length) {
      this.skipWhitespace();
      if (this.pos >= this.src.length) break;

      const ch = this.src[this.pos];

      // 주석
      if (ch === '/' && this.src[this.pos + 1] === '/') {
        while (this.pos < this.src.length && this.src[this.pos] !== '\n') this.pos++;
        continue;
      }

      // 숫자 (정수, 실수, 과학적 표기)
      if (this.isDigit(ch) || (ch === '.' && this.isDigit(this.src[this.pos + 1]))) {
        tokens.push(this.readNumber());
        continue;
      }

      // 문자열
      if (ch === '"') { tokens.push(this.readString()); continue; }

      // 식별자 / 키워드
      if (this.isAlpha(ch)) { tokens.push(this.readIdentifier()); continue; }

      // 2자 연산자
      const two = this.src.slice(this.pos, this.pos + 2);
      const twoMap: Record<string, TokenType> = {
        '==': TokenType.EQ, '!=': TokenType.NEQ,
        '<=': TokenType.LTE, '>=': TokenType.GTE,
        '&&': TokenType.AND, '||': TokenType.OR,
        '->': TokenType.ARROW,
      };
      if (twoMap[two]) {
        tokens.push({ type: twoMap[two], value: two, line: this.line, col: this.col });
        this.pos += 2; this.col += 2; continue;
      }

      // 1자 연산자
      const oneMap: Record<string, TokenType> = {
        '+': TokenType.PLUS, '-': TokenType.MINUS,
        '*': TokenType.STAR, '/': TokenType.SLASH,
        '%': TokenType.PERCENT, '^': TokenType.CARET,
        '<': TokenType.LT, '>': TokenType.GT,
        '=': TokenType.ASSIGN, '!': TokenType.NOT,
        '(': TokenType.LPAREN, ')': TokenType.RPAREN,
        '[': TokenType.LBRACKET, ']': TokenType.RBRACKET,
        '{': TokenType.LBRACE, '}': TokenType.RBRACE,
        ',': TokenType.COMMA, '.': TokenType.DOT,
        ';': TokenType.SEMICOLON, ':': TokenType.COLON,
      };
      if (oneMap[ch]) {
        tokens.push({ type: oneMap[ch], value: ch, line: this.line, col: this.col });
        this.pos++; this.col++; continue;
      }

      // 개행
      if (ch === '\n') {
        this.line++; this.col = 1; this.pos++; continue;
      }

      this.pos++; // 알 수 없는 문자 스킵
    }
    tokens.push({ type: TokenType.EOF, value: '', line: this.line, col: this.col });
    return tokens;
  }

  private readNumber(): Token {
    const start = this.pos;
    const startCol = this.col;
    while (this.pos < this.src.length && (this.isDigit(this.src[this.pos]) || this.src[this.pos] === '.')) {
      this.pos++; this.col++;
    }
    // 과학적 표기 e.g. 1.5e10, 3e-4
    if (this.src[this.pos] === 'e' || this.src[this.pos] === 'E') {
      this.pos++; this.col++;
      if (this.src[this.pos] === '+' || this.src[this.pos] === '-') { this.pos++; this.col++; }
      while (this.isDigit(this.src[this.pos])) { this.pos++; this.col++; }
    }
    return { type: TokenType.NUMBER, value: this.src.slice(start, this.pos), line: this.line, col: startCol };
  }

  private readString(): Token {
    const startCol = this.col;
    this.pos++; this.col++;
    let val = '';
    while (this.pos < this.src.length && this.src[this.pos] !== '"') {
      val += this.src[this.pos]; this.pos++; this.col++;
    }
    this.pos++; this.col++;
    return { type: TokenType.STRING, value: val, line: this.line, col: startCol };
  }

  private readIdentifier(): Token {
    const start = this.pos;
    const startCol = this.col;
    while (this.pos < this.src.length && (this.isAlpha(this.src[this.pos]) || this.isDigit(this.src[this.pos]) || this.src[this.pos] === '_')) {
      this.pos++; this.col++;
    }
    const val = this.src.slice(start, this.pos);
    const type = KEYWORDS[val] ?? TokenType.IDENTIFIER;
    return { type, value: val, line: this.line, col: startCol };
  }

  private skipWhitespace() {
    while (this.pos < this.src.length && (this.src[this.pos] === ' ' || this.src[this.pos] === '\t' || this.src[this.pos] === '\r')) {
      this.pos++; this.col++;
    }
  }

  private isDigit(c: string) { return c >= '0' && c <= '9'; }
  private isAlpha(c: string) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_'; }
}
