// FreeLang Science - Parser

import { Token, TokenType } from '../lexer/token';
import * as AST from './ast';

export class Parser {
  private pos = 0;

  constructor(private tokens: Token[]) {}

  parse(): AST.Program {
    const body: AST.ASTNode[] = [];
    while (!this.isEOF()) {
      body.push(this.parseStatement());
    }
    return { kind: 'Program', body };
  }

  private parseStatement(): AST.ASTNode {
    const t = this.current();
    if (t.type === TokenType.FN)     return this.parseFunctionDef();
    if (t.type === TokenType.LET)    return this.parseLetStmt();
    if (t.type === TokenType.CONST)  return this.parseConstStmt();
    if (t.type === TokenType.RETURN) return this.parseReturnStmt();
    if (t.type === TokenType.IF)     return this.parseIfStmt();
    if (t.type === TokenType.FOR)    return this.parseForStmt();
    if (t.type === TokenType.IMPORT) return this.parseImportStmt();
    return this.parseExprStmt();
  }

  private parseFunctionDef(): AST.FunctionDef {
    this.expect(TokenType.FN);
    const name = this.expect(TokenType.IDENTIFIER).value;
    this.expect(TokenType.LPAREN);
    const params: AST.Param[] = [];
    while (this.current().type !== TokenType.RPAREN) {
      const pname = this.expect(TokenType.IDENTIFIER).value;
      let type: string | undefined;
      if (this.current().type === TokenType.COLON) { this.advance(); type = this.advance().value; }
      params.push({ name: pname, type });
      if (this.current().type === TokenType.COMMA) this.advance();
    }
    this.expect(TokenType.RPAREN);
    let returnType: string | undefined;
    if (this.current().type === TokenType.ARROW) { this.advance(); returnType = this.advance().value; }
    this.expect(TokenType.LBRACE);
    const body = this.parseBlock();
    this.expect(TokenType.RBRACE);
    return { kind: 'FunctionDef', name, params, returnType, body };
  }

  private parseLetStmt(): AST.LetStmt {
    this.expect(TokenType.LET);
    const name = this.expect(TokenType.IDENTIFIER).value;
    let type: string | undefined;
    if (this.current().type === TokenType.COLON) { this.advance(); type = this.advance().value; }
    this.expect(TokenType.ASSIGN);
    const value = this.parseExpr();
    this.skipSemicolon();
    return { kind: 'LetStmt', name, type, value };
  }

  private parseConstStmt(): AST.ConstStmt {
    this.expect(TokenType.CONST);
    const name = this.expect(TokenType.IDENTIFIER).value;
    let type: string | undefined;
    if (this.current().type === TokenType.COLON) { this.advance(); type = this.advance().value; }
    this.expect(TokenType.ASSIGN);
    const value = this.parseExpr();
    this.skipSemicolon();
    return { kind: 'ConstStmt', name, type, value };
  }

  private parseReturnStmt(): AST.ReturnStmt {
    this.expect(TokenType.RETURN);
    if (this.current().type === TokenType.SEMICOLON || this.current().type === TokenType.RBRACE) {
      this.skipSemicolon();
      return { kind: 'ReturnStmt' };
    }
    const value = this.parseExpr();
    this.skipSemicolon();
    return { kind: 'ReturnStmt', value };
  }

  private parseIfStmt(): AST.IfStmt {
    this.expect(TokenType.IF);
    const cond = this.parseExpr();
    this.expect(TokenType.LBRACE);
    const then = this.parseBlock();
    this.expect(TokenType.RBRACE);
    let else_: AST.ASTNode[] | undefined;
    if (this.current().type === TokenType.ELSE) {
      this.advance();
      this.expect(TokenType.LBRACE);
      else_ = this.parseBlock();
      this.expect(TokenType.RBRACE);
    }
    return { kind: 'IfStmt', cond, then, else_ };
  }

  private parseForStmt(): AST.ForStmt {
    this.expect(TokenType.FOR);
    const init = this.parseStatement();
    const cond = this.parseExpr();
    this.skipSemicolon();
    const step = this.parseExpr();
    this.expect(TokenType.LBRACE);
    const body = this.parseBlock();
    this.expect(TokenType.RBRACE);
    return { kind: 'ForStmt', init, cond, step, body };
  }

  private parseImportStmt(): AST.ImportStmt {
    this.expect(TokenType.IMPORT);
    const module = this.expect(TokenType.IDENTIFIER).value;
    this.skipSemicolon();
    return { kind: 'ImportStmt', module };
  }

  private parseExprStmt(): AST.ExprStmt {
    const expr = this.parseExpr();
    this.skipSemicolon();
    return { kind: 'ExprStmt', expr };
  }

  private parseBlock(): AST.ASTNode[] {
    const stmts: AST.ASTNode[] = [];
    while (!this.isEOF() && this.current().type !== TokenType.RBRACE) {
      stmts.push(this.parseStatement());
    }
    return stmts;
  }

  // 표현식 파싱 (우선순위: 비교 < 덧셈 < 곱셈 < 단항 < 호출)
  private parseExpr(): AST.ASTNode { return this.parseComparison(); }

  private parseComparison(): AST.ASTNode {
    let left = this.parseAddSub();
    while ([TokenType.EQ, TokenType.NEQ, TokenType.LT, TokenType.GT, TokenType.LTE, TokenType.GTE].includes(this.current().type as TokenType)) {
      const op = this.advance().value;
      left = { kind: 'BinaryExpr', op, left, right: this.parseAddSub() };
    }
    return left;
  }

  private parseAddSub(): AST.ASTNode {
    let left = this.parseMulDiv();
    while (this.current().type === TokenType.PLUS || this.current().type === TokenType.MINUS) {
      const op = this.advance().value;
      left = { kind: 'BinaryExpr', op, left, right: this.parseMulDiv() };
    }
    return left;
  }

  private parseMulDiv(): AST.ASTNode {
    let left = this.parsePower();
    while ([TokenType.STAR, TokenType.SLASH, TokenType.PERCENT].includes(this.current().type as TokenType)) {
      const op = this.advance().value;
      left = { kind: 'BinaryExpr', op, left, right: this.parsePower() };
    }
    return left;
  }

  private parsePower(): AST.ASTNode {
    let base = this.parseUnary();
    if (this.current().type === TokenType.CARET) {
      const op = this.advance().value;
      return { kind: 'BinaryExpr', op, left: base, right: this.parsePower() };
    }
    return base;
  }

  private parseUnary(): AST.ASTNode {
    if (this.current().type === TokenType.MINUS || this.current().type === TokenType.NOT) {
      const op = this.advance().value;
      return { kind: 'UnaryExpr', op, expr: this.parseUnary() };
    }
    return this.parsePostfix();
  }

  private parsePostfix(): AST.ASTNode {
    let expr = this.parsePrimary();
    while (true) {
      if (this.current().type === TokenType.LPAREN) {
        this.advance();
        const args: AST.ASTNode[] = [];
        while (this.current().type !== TokenType.RPAREN) {
          args.push(this.parseExpr());
          if (this.current().type === TokenType.COMMA) this.advance();
        }
        this.expect(TokenType.RPAREN);
        expr = { kind: 'CallExpr', callee: expr, args };
      } else if (this.current().type === TokenType.LBRACKET) {
        this.advance();
        const index = this.parseExpr();
        this.expect(TokenType.RBRACKET);
        expr = { kind: 'IndexExpr', obj: expr, index };
      } else if (this.current().type === TokenType.DOT) {
        this.advance();
        const prop = this.expect(TokenType.IDENTIFIER).value;
        expr = { kind: 'MemberExpr', obj: expr, prop };
      } else break;
    }
    return expr;
  }

  private parsePrimary(): AST.ASTNode {
    const t = this.current();
    if (t.type === TokenType.NUMBER) {
      this.advance();
      return { kind: 'NumberLit', value: parseFloat(t.value) };
    }
    if (t.type === TokenType.STRING) {
      this.advance();
      return { kind: 'StringLit', value: t.value };
    }
    if (t.type === TokenType.TRUE)  { this.advance(); return { kind: 'BoolLit', value: true }; }
    if (t.type === TokenType.FALSE) { this.advance(); return { kind: 'BoolLit', value: false }; }
    if (t.type === TokenType.IDENTIFIER) {
      this.advance();
      return { kind: 'Identifier', name: t.value };
    }
    if (t.type === TokenType.LPAREN) {
      this.advance();
      const expr = this.parseExpr();
      this.expect(TokenType.RPAREN);
      return expr;
    }
    if (t.type === TokenType.LBRACKET) {
      return this.parseArrayOrMatrix();
    }
    throw new Error(`예상치 못한 토큰: ${t.value} (${t.type}) at ${t.line}:${t.col}`);
  }

  private parseArrayOrMatrix(): AST.ArrayLit | AST.MatrixLit {
    this.expect(TokenType.LBRACKET);
    const elements: AST.ASTNode[] = [];
    while (this.current().type !== TokenType.RBRACKET && !this.isEOF()) {
      elements.push(this.parseExpr());
      if (this.current().type === TokenType.COMMA) this.advance();
    }
    this.expect(TokenType.RBRACKET);
    return { kind: 'ArrayLit', elements };
  }

  private expect(type: TokenType): Token {
    const t = this.current();
    if (t.type !== type) throw new Error(`기대: ${type}, 실제: ${t.type} ('${t.value}') at ${t.line}:${t.col}`);
    return this.advance();
  }

  private advance(): Token { return this.tokens[this.pos++]; }
  private current(): Token { return this.tokens[this.pos] ?? { type: TokenType.EOF, value: '', line: 0, col: 0 }; }
  private isEOF(): boolean { return this.current().type === TokenType.EOF; }
  private skipSemicolon() { if (this.current().type === TokenType.SEMICOLON) this.advance(); }
}
