fn permutation(n: int, r: int) -> int { return factorial(n) / factorial(n - r) }
fn combination(n: int, r: int) -> int { return factorial(n) / (factorial(r) * factorial(n - r)) }

// GCD / LCM
fn gcd(a: int, b: int) -> int { if b == 0 { return a } return gcd(b, a % b) }
fn lcm(a: int, b: int) -> int { return a / gcd(a, b) * b }
