// FreeLang Science - 통계 모듈

export const SCI_STATS_FUNCTIONS = `
// 기술 통계
fn sum(arr: float[], n: int) -> float {
  let s: float = 0.0
  for let i: int = 0; i < n; i = i + 1 {
    s = s + arr[i]
  }
  return s
}

fn mean(arr: float[], n: int) -> float { return sum(arr, n) / n }

fn variance(arr: float[], n: int) -> float {
  let m: float = mean(arr, n)
  let s: float = 0.0
  for let i: int = 0; i < n; i = i + 1 {
    let d: float = arr[i] - m
    s = s + d * d
  }
  return s / n
}

fn stddev(arr: float[], n: int) -> float { return sqrt(variance(arr, n)) }

fn median(arr: float[], n: int) -> float {
  // 정렬 필요 (버블 정렬 사용)
  // 실제 구현에서는 정렬 후 중앙값 반환
  return arr[n / 2]
}

fn array_min(arr: float[], n: int) -> float {
  let m: float = arr[0]
  for let i: int = 1; i < n; i = i + 1 {
    if arr[i] < m { m = arr[i] }
  }
  return m
}

fn array_max(arr: float[], n: int) -> float {
  let m: float = arr[0]
  for let i: int = 1; i < n; i = i + 1 {
    if arr[i] > m { m = arr[i] }
  }
  return m
}

fn range_stat(arr: float[], n: int) -> float {
  return array_max(arr, n) - array_min(arr, n)
}

// 확률 분포
fn normal_pdf(x: float, mu: float, sigma: float) -> float {
  let z: float = (x - mu) / sigma
  return exp(-0.5 * z * z) / (sigma * sqrt(2.0 * PI))
}

fn normal_cdf(x: float, mu: float, sigma: float) -> float {
  let z: float = (x - mu) / (sigma * sqrt(2.0))
  return 0.5 * (1.0 + erf(z))
}

// 선형 회귀
fn linear_regression_slope(x: float[], y: float[], n: int) -> float {
  let mx: float = mean(x, n)
  let my: float = mean(y, n)
  let num: float = 0.0
  let den: float = 0.0
  for let i: int = 0; i < n; i = i + 1 {
    num = num + (x[i] - mx) * (y[i] - my)
    den = den + (x[i] - mx) * (x[i] - mx)
  }
  return num / den
}

fn linear_regression_intercept(x: float[], y: float[], n: int) -> float {
  return mean(y, n) - linear_regression_slope(x, y, n) * mean(x, n)
}

fn correlation(x: float[], y: float[], n: int) -> float {
  let mx: float = mean(x, n)
  let my: float = mean(y, n)
  let num: float = 0.0
  let dx: float = 0.0
  let dy: float = 0.0
  for let i: int = 0; i < n; i = i + 1 {
    num = num + (x[i] - mx) * (y[i] - my)
    dx = dx + (x[i] - mx) * (x[i] - mx)
    dy = dy + (y[i] - my) * (y[i] - my)
  }
  return num / sqrt(dx * dy)
}

// erf 근사 (Abramowitz & Stegun)
fn erf(x: float) -> float {
  let t: float = 1.0 / (1.0 + 0.3275911 * abs(x))
  let y: float = 1.0 - (0.254829592 * t - 0.284496736 * t * t + 1.421413741 * t * t * t - 1.453152027 * t * t * t * t + 1.061405429 * t * t * t * t * t) * exp(-x * x)
  if x < 0 { return -y }
  return y
}
